/**
 * Parameter catalog for the stable-diffusion.cpp server (sdiffusion kind).
 *
 * These are the `sd-server` options the GUI's Server tab always shows
 * (docs/stable-diffusion.md §3.9). Like the strata and audio.cpp server lists,
 * this set ships with the app rather than living in `.config` — it is fixed by
 * the server's own parser (`examples/server/main.cpp`), and the rows the launch
 * path depends on (`--listen-ip`, `--listen-port`, `--model-dir`) must always be
 * present. The full engine vocabulary stays user-editable in
 * `.config/params.sdiffusion.json` (generated by `npm run gen:sd-params`).
 *
 * Two rules worth remembering:
 *  - The port flag is **`--listen-port`**, not `--port`; `-l` is the listen IP.
 *  - **`--model-dir` is required**, not optional: the instance launches with no
 *    weight flags and every model arrives over `POST /sdcpp/v1/models/load`,
 *    which resolves catalog file-ids under these roots (§1.4.1). It repeats,
 *    once per model folder, and root order decides which file-ids carry the
 *    `@<hash>/` root qualifier (§1.3.1).
 *
 * `inputType: 'toggle'` rows are bare on/off flags; the rest take a value.
 */

import type { ParamDef } from '../modelConfig.js';

export const SD_SERVER_PARAMS: ParamDef[] = [
  // --- Network ---
  { flag: '--listen-ip', key: 'listen-ip', label: 'Host', description: 'Address to listen on: 127.0.0.1 = this PC only, 0.0.0.0 = also other devices', category: 'network', inputType: 'text', default: '127.0.0.1' },
  { flag: '--listen-port', key: 'listen-port', label: 'Port', description: 'HTTP port to bind (sd-server has no --port flag)', category: 'network', inputType: 'number', default: '8080' },

  // --- Model roots (repeat one per model folder) ---
  { flag: '--model-dir', key: 'model-dir', label: 'Model Folder', description: 'A model root: a folder whose immediate subfolders are the component categories (diffusion_models/, text_encoders/, vae/, checkpoints/). Repeat once per model folder — required, because models are loaded over the API and never passed as weight flags. The first root gets plain file-ids; later roots are addressed as @<hash>/…', category: 'model', inputType: 'path' },
  { flag: '--lora-model-dir', key: 'lora-model-dir', label: 'LoRA Dir', description: 'Single LoRA directory. Leave empty to keep per-root loras/ discovery — setting this disables that for every model root', category: 'model', inputType: 'path' },
  { flag: '--embd-dir', key: 'embd-dir', label: 'Embeddings Dir', description: 'Directory of textual-inversion embeddings', category: 'model', inputType: 'path' },
  { flag: '--hires-upscalers-dir', key: 'hires-upscalers-dir', label: 'Highres Upscaler Dir', description: 'Directory of highres-fix upscaler models selectable by name', category: 'model', inputType: 'path' },

  // --- Device placement (plain text rows in v1, §5 Q5) ---
  { flag: '--backend', key: 'backend', label: 'Backend', description: 'Weight placement per module, e.g. diffusion=CUDA0,te=CUDA1,vae=CUDA1. Module keys: diffusion, te, clipvision, vae, controlnet, photomaker, upscaler, detector, audioencoder. & assigns several devices to one module. Applies to every model loaded over the API', category: 'device', inputType: 'text' },
  { flag: '--params-backend', key: 'params-backend', label: 'Params Backend', description: 'Where weights live: disk, cpu or per-module assignments (diffusion=disk,te=cpu). Setting this disables --auto-fit', category: 'device', inputType: 'text' },
  { flag: '--split-mode', key: 'split-mode', label: 'Split Mode', description: 'How a module assigned several devices is split: layer (whole blocks, default) or row (matmul rows, CUDA only)', category: 'device', inputType: 'select', options: ['layer', 'row'] },
  { flag: '--max-vram', key: 'max-vram', label: 'Max VRAM (GiB)', description: 'Per-device weight budget, e.g. 6 or CUDA0=6,CUDA1=4. 0 = use live free VRAM; negative reserves that much free', category: 'device', inputType: 'text' },
  { flag: '--auto-fit', key: 'auto-fit', label: 'Auto Fit', description: 'Keep --backend as given and place weights on the compute GPU, RAM, another GPU or disk by available memory. On unless --params-backend is set', category: 'device', inputType: 'select', options: ['on', 'off'], default: 'on' },
  { flag: '--threads', key: 'threads', label: 'Threads', description: 'CPU threads; <= 0 means physical core count', category: 'device', inputType: 'number', default: '-1' },

  // --- Memory / speed ---
  { flag: '--offload-to-cpu', key: 'offload-to-cpu', label: 'Offload To CPU', description: 'Keep weights in RAM and page them into VRAM on demand. Usually unnecessary when --auto-fit is on', category: 'memory', inputType: 'toggle' },
  { flag: '--mmap', key: 'mmap', label: 'Memory-map Models', description: 'Read weights by mmap instead of loading them', category: 'memory', inputType: 'toggle' },
  { flag: '--conditioning-cache-size', key: 'conditioning-cache-size', label: 'Conditioning Cache', description: 'Conditioning results cached per context; 0 disables', category: 'memory', inputType: 'number', default: '0' },
  { flag: '--flash-attn', key: 'flash-attn', label: 'Flash Attention', description: 'on|off|auto, or per-module (auto,te=off,vae=on)', category: 'memory', inputType: 'text' },
  { flag: '--conv-direct', key: 'conv-direct', label: 'Direct Convolution', description: 'on|off|auto, or per-module (auto,vae=off)', category: 'memory', inputType: 'text' },
  { flag: '--type', key: 'type', label: 'Weight Type', description: 'Quantize at load time (f32, f16, q8_0, q4_K, …). Leave empty for pre-quantized GGUF — the file type is already correct', category: 'memory', inputType: 'preset', presets: ['f32', 'f16', 'q8_0', 'q5_0', 'q5_1', 'q4_0', 'q4_1', 'q2_K', 'q3_K', 'q4_K'] },

  // --- Logging ---
  { flag: '--log-level', key: 'log-level', label: 'Log Level', description: 'Minimum log level shown in the log view', category: 'logging', inputType: 'select', options: ['debug', 'verbose', 'info', 'warn', 'error'], default: 'info' },
];
